    }

    if open_bins_count > 1 && mean < item * 0.58 {
        score += (item - mean).max(0.0) * 0.09;
    }

    // Opening is attractive early, but only when the existing alternatives are poor.
    if residual == bin_capacity {
        let opening_pressure = 0.48 + 0.34 * progress + 0.24 * item_ratio + 0.12 * next_ratio;
        let option_penalty = if fitting_bins_count == 0 {
            0.0
        } else {
            (1.0 / (fitting_bins_count as f64).sqrt()) * 0.28
        };
        score += capacity * (opening_pressure + option_penalty);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let mean = mean_residual as f64;
    let next = next_item_size as f64;

    let fit_ratio = (residual / capacity).clamp(0.0, 1.0);
    let post_ratio = (post / capacity).clamp(0.0, 1.0);
    let item_ratio = (item / capacity).clamp(0.0, 1.0);
    let next_ratio = (next / capacity).clamp(0.0, 1.0);

    let dead_space = (capacity - post).max(0.0);
    let dead_ratio = (dead_space / capacity).clamp(0.0, 1.0);
    let near_dead_ratio = if post_ratio < 0.12 {
        1.0
    } else if post_ratio < 0.24 {
        (0.24 - post_ratio) / 0.12
    } else {
        0.0
    };
    let waste_ratio = if fit_ratio > 0.0 {
        (1.0 - fit_ratio).powf(1.35)
    } else {
        1.0
    };
    let post_waste = 1.0 - post_ratio;
    let future_pressure = next_ratio;
    let scarcity = if fitting_bins_count == 0 {
        1.0
    } else {
        1.0 / (fitting_bins_count as f64).sqrt()
    };

    let mut score = post * 2.15 + post_waste * capacity * 0.85;
    score += waste_ratio * capacity * 1.45;
    score -= future_pressure * capacity * 0.32;
    score -= mean * 0.18;
    score += scarcity * capacity * 0.12;

    let fragmentation = (post_waste * post_waste).sqrt();
    let stranded_space = if post < item {
        post
    } else {
        0.0
    };
    score += fragmentation * capacity * 0.34;
    score += stranded_space * 0.19;
    score -= (post_ratio * post_ratio) * capacity * 0.11;

    let dead_gap = (item - post).max(0.0);
    let dead_gap_ratio = (dead_gap / capacity).clamp(0.0, 1.0);
    score += dead_gap_ratio * capacity * 0.42;
    score += near_dead_ratio * capacity * 0.16;

    if post < item * 0.08 {
        score -= capacity * 0.13;
    } else if post < item * 0.18 {
        score -= capacity * 0.08;
    }

    if post == 0 {
        score -= capacity * 0.28;
    }

    if residual == bin_capacity {
        let occupancy_pressure = (step_index as f64 / total_items.max(1) as f64).min(1.0);
        let adaptive_penalty = capacity
            * (0.72 + 0.38 * occupancy_pressure)
            * (1.0 + 0.22 * item_ratio + 0.10 * next_ratio);
        score += adaptive_penalty;
    }

    if fitting_bins_count == 1 && residual != bin_capacity {
        let critical_space = (residual - next).max(0.0);
        score -= critical_space * 0.16;
    }

    if open_bins_count > 1 && mean < item * 0.65 {
        score += (item - mean).max(0.0) * 0.12;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: u32) -> f64 {
    let capacity = bin_capacity.max(1) as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let mean = mean_residual as f64;
    let next = next_item_size as f64;

    let item_ratio = (item / capacity).clamp(0.0, 1.0);
    let fit_ratio = (residual / capacity).clamp(0.0, 1.0);
    let post_ratio = (post / capacity).clamp(0.0, 1.0);
    let next_ratio = (next / capacity).clamp(0.0, 1.0);

    let mut score = post * 1.72;
    score += (capacity - post) * 0.31;
    score += capacity * (1.0 - fit_ratio) * 0.47;

    let dead_fraction = 1.0 - post_ratio;
    let smooth_dead = dead_fraction * dead_fraction * (3.0 - 2.0 * dead_fraction);
    score += capacity * smooth_dead * 0.76;

    let stranded_fraction = (post / item).min(1.0);
    if post < item {
        score += capacity * (1.0 - stranded_fraction) * (1.0 - stranded_fraction) * 0.64;
    }

    let scarcity = 1.0 / (fitting_bins_count.max(1) as f64).sqrt();
    score += capacity * scarcity * 0.11 * (0.65 + 0.55 * item_ratio);

    let mean_gap = (post - mean).abs() / capacity;
    score += capacity * mean_gap * 0.085;

    let next_gap = (next - post).max(0.0);
    if next > post {
        let next_miss = next_gap / capacity;
        score += capacity * next_miss * next_miss * 0.29;
    }

    if post <= next * 0.12 {
        score -= capacity * 0.09;
    } else if post <= next * 0.25 && post < item {
        score -= capacity * 0.035;
    }

    if post == 0.0 {
        score -= capacity * 0.28;
    }

    if fitting_bins_count == 1 && residual != bin_capacity {
        let useful_gap = (post - next).max(0.0);
        score -= useful_gap * 0.17;
    }

    let mean_deficit = (mean - item).max(0.0) / capacity;
    let pressure = mean_deficit * (0.55 + 0.45 * item_ratio);
    if open_bins_count > 1 {
        score += capacity * pressure * 0.14;
    }

    if residual == bin_capacity {
        let progress = (step_index as f64 / total_items.max(1) as f64).min(1.0);
        let new_bin_cost = capacity * (
            0.61
            + 0.27 * progress
            + 0.34 * item_ratio
            + 0.09 * next_ratio
            + 0.18 * scarcity
            - 0.08 * mean_deficit
        );
        score += new_bin_cost;
    } else {
        let tight_fit = ((item - residual) / item).clamp(0.0, 1.0);
        let close_enough = 1.0 - (residual / capacity).min(1.0);
        score -= capacity * tight_fit * close_enough * 0.12;
    }

    score
}
